33	public class DocumentIO {
34	    public static final String EXTRA_DOCUMENT = "EXTRA_DOCUMENT"; // Document
35	    public static final String EXTRA_PATH = "EXTRA_PATH"; // java.io.File
36	    public static final String EXTRA_PATH_IS_FOLDER = "EXTRA_PATH_IS_FOLDER"; // boolean
37	    public static final String EXTRA_ALLOW_RENAME = "EXTRA_ALLOW_RENAME";
38	
39	    public static final int MAX_TITLE_EXTRACTION_LENGTH = 25;
40	
41	
42	    public static Document loadDocument(Context context, Intent arguments, @Nullable Document existingDocument) {
43	        if (existingDocument != null) {
44	            return existingDocument;
45	        }
46	
47	        Bundle bundle = new Bundle();
48	        if (arguments.hasExtra(EXTRA_DOCUMENT)) {
49	            bundle.putSerializable(EXTRA_DOCUMENT, arguments.getSerializableExtra(EXTRA_DOCUMENT));
50	        } else {
51	            bundle.putBoolean(EXTRA_ALLOW_RENAME, arguments.getBooleanExtra(EXTRA_ALLOW_RENAME, true));
52	            bundle.putSerializable(EXTRA_PATH, arguments.getSerializableExtra(EXTRA_PATH));
53	            bundle.putBoolean(EXTRA_PATH_IS_FOLDER, arguments.getBooleanExtra(EXTRA_PATH_IS_FOLDER, false));
54	        }
55	        return loadDocument(context, bundle, existingDocument);
56	    }
57	
58	    @SuppressWarnings({"ConstantConditions", "ResultOfMethodCallIgnored"})
59	    public static synchronized Document loadDocument(Context context, Bundle arguments, @Nullable Document existingDocument) {
60	        if (existingDocument != null) {
61	            return existingDocument;
62	        }
63	
64	        // When called directly from a filepath
65	        if (arguments.containsKey(EXTRA_DOCUMENT)) {
66	            return (Document) arguments.getSerializable(EXTRA_DOCUMENT);
67	        }
68	
69	        Document document = new Document();
70	        document.setDoHistory(false);
71	        document.setFileExtension(MarkdownTextConverter.EXT_MARKDOWN__MD);
72	        File extraPath = (File) arguments.getSerializable(EXTRA_PATH);
73	        File filePath = extraPath;
74	
75	        // Generate random not existing filepath if filename not specified
76	        boolean extraPathIsFolder = arguments.getBoolean(EXTRA_PATH_IS_FOLDER);
77	        if (extraPathIsFolder) {
78	            extraPath.mkdirs();
79	            while (filePath.exists()) {
80	                filePath = new File(extraPath, String.format("%s-%s.%s", context.getString(R.string.document_one), UUID.randomUUID().toString(), MarkdownTextConverter.EXT_MARKDOWN__MD));
81	            }
82	        } else if (filePath.isFile() && filePath.canRead()) {
83	            // Extract existing extension
84	            for (String ext : MarkdownTextConverter.MD_EXTENSIONS) {
85	                if (filePath.getName().toLowerCase(Locale.getDefault()).endsWith(ext)) {
86	                    document.setFileExtension(ext);
87	                    break;
88	                }
89	            }
90	
91	            // Extract content and title
92	            document.setTitle(MarkdownTextConverter.MD_EXTENSION_PATTERN.matcher(filePath.getName()).replaceAll(""));
93	            document.setContent(FileUtils.readTextFile(filePath));
94	        }
95	
96	        document.setFile(filePath);
97	
98	        if (document.getFormat() == TextFormat.FORMAT_UNKNOWN) {
99	            String fnlower = document.getFile().getName().toLowerCase();
100	            document.setFormat(TextFormat.FORMAT_MARKDOWN);
101	            if (TodoTxtTextConverter.TODOTXT_FILE_PATTERN.matcher(fnlower).matches()) {
102	                document.setFormat(TextFormat.FORMAT_TODOTXT);
103	            }
104	        }
105	
106	        document.setDoHistory(true);
107	        return document;
108	    }
109	
110	    public static synchronized boolean saveDocument(Document document, boolean argAllowRename, String currentText) {
111	        boolean ret = false;
112	        String filename = DocumentIO.normalizeTitleForFilename(document) + document.getFileExtension();
113	        document.setDoHistory(true);
114	        document.setFile(new File(document.getFile().getParentFile(), filename));
115	
116	        Document documentInitial = document.getInitialVersion();
117	        if (argAllowRename) {
118	            if (!document.getFile().equals(documentInitial.getFile())) {
119	                if (documentInitial.getFile().exists()) {
120	                    if (FileUtils.renameFile(documentInitial.getFile(), document.getFile())) {
121	                        // Rename succeeded -> Rename everything in history too
122	                        for (Document hist : document.getHistory()) {
123	                            hist.setFile(document.getFile());
124	                            for (Document hist2 : hist.getHistory()) {
125	                                hist2.setFile(document.getFile());
126	                            }
127	                        }
128	                    }
129	                }
130	            }
131	        } else {
132	            document.setFile(documentInitial.getFile());
133	        }
134	
135	        if (!currentText.equals(documentInitial.getContent())) {
136	            document.forceAddNextChangeToHistory();
137	            document.setContent(currentText);
138	            ret = FileUtils.writeFile(document.getFile(), document.getContent());
139	        } else {
140	            ret = true;
141	        }
142	        return ret;
143	    }
144	
145	    public static String normalizeTitleForFilename(Document _document) {
146	        String name = _document.getTitle();
147	        if (name.length() == 0) {
148	            if (_document.getContent().length() == 0) {
149	                return null;
150	            } else {
151	                String contentL1 = _document.getContent().split("\n")[0];
152	                if (contentL1.length() < MAX_TITLE_EXTRACTION_LENGTH) {
153	                    name = contentL1.substring(0, contentL1.length());
154	                } else {
155	                    name = contentL1.substring(0, MAX_TITLE_EXTRACTION_LENGTH);
156	                }
157	            }
158	        }
159	        name = name.replaceAll("[\\\\/:\"´`'*$?<>\n\r@|#]+", "").trim();
160	
161	        if (name.isEmpty()) {
162	            name = "Note " + UUID.randomUUID().toString();
163	        }
164	        return name;
165	    }
166	
167	    public static final InputFilter INPUT_FILTER_FILESYSTEM_FILENAME = new InputFilter() {
168	        private final String blockCharacterSet = "\\/:\"´`'*?<>\n\r@|";
169	
170	        public CharSequence filter(CharSequence source, int start, int end, Spanned dest, int dstart, int dend) {
171	            for (int i = 0; !TextUtils.isEmpty(source) && i < source.length(); i++) {
172	                if (blockCharacterSet.contains(("" + source.charAt(i)))) {
173	                    return "";
174	                }
175	            }
176	            return null;
177	        }
178	    };
179	}
