// Remember the current cursor position so it can be restored later on
private void rememberEditorCursorPosition() {
    if (_hlEditor != null && _hlEditor.getSelectionStart() >= 0) {
        _lastEditorCursorPosition = _hlEditor.getSelectionStart();
    }
}

// Move the cursor to the given position (clamped into the valid range)
private void setEditorCursorPosition(int position) {
    if (_hlEditor == null) {
        return;
    }
    position = Math.min(Math.max(position, 0), _hlEditor.length());
    _hlEditor.setSelection(position);
    _lastEditorCursorPosition = position;
}

@Override
public void onSaveInstanceState(@NonNull Bundle outState) {
    rememberEditorCursorPosition();
    saveDocument();
    outState.putSerializable(SAVESTATE_DOCUMENT, _document);
    outState.putInt(SAVESTATE_CURSOR_POS, _lastEditorCursorPosition);
    super.onSaveInstanceState(outState);
}

